#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cstdint>

#define OC_TILE 16
template <int KERNEL_H, int KERNEL_W>
__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    const int N,
    const int in_channels,
    const int out_channels,
    const int H, const int W,
    const int H_out, const int W_out,
    const int kernel_h, const int kernel_w,
    const int stride_h, const int stride_w,
    const int padding_h, const int padding_w,
    const int dilation_h, const int dilation_w,
    const int groups,
    const int in_channels_per_group,
    const int out_channels_per_group,
    const int elements_per_tile)
{
    extern __shared__ float s_weight[];
    const int g = blockIdx.x;
    const int tile_idx = blockIdx.y;
    const int weight_group_size = in_channels_per_group * out_channels_per_group * kernel_h * kernel_w;
    const float* weight_group_ptr = weight + (size_t)g * weight_group_size;
    if ((weight_group_size % 4 == 0) && ((reinterpret_cast<uintptr_t>(weight_group_ptr) & 0xF) == 0)) {
        const int vec_count = weight_group_size / 4;
        const float4* weight_group_ptr4 = reinterpret_cast<const float4*>(weight_group_ptr);
        float4* s_weight4 = reinterpret_cast<float4*>(s_weight);
        for (int i = threadIdx.x; i < vec_count; i += blockDim.x) {
            s_weight4[i] = weight_group_ptr4[i];
        }
    } else {
        for (int i = threadIdx.x; i < weight_group_size; i += blockDim.x) {
            s_weight[i] = weight_group_ptr[i];
        }
    }
    __syncthreads();
    const int kh_bound = (KERNEL_H > 0) ? KERNEL_H : kernel_h;
    const int kw_bound = (KERNEL_W > 0) ? KERNEL_W : kernel_w;
    const int spatial_elems = H_out * W_out;
    const int e_start = tile_idx * elements_per_tile;
    const int e_end = e_start + elements_per_tile < spatial_elems ? e_start + elements_per_tile : spatial_elems;
    const int kernel_hw = kernel_h * kernel_w;
    // Weight tile for this group is staged once in shared memory above and reused
    // across all N samples in the batch, avoiding redundant shared-memory loads
    // and synchronizations that previously happened once per (n, g) block.
    for (int n = 0; n < N; ++n) {
        for (int e = e_start + threadIdx.x; e < e_end; e += blockDim.x) {
            int ow = e % W_out;
            int oh = e / W_out;
            for (int oc_start = 0; oc_start < out_channels_per_group; oc_start += OC_TILE) {
                int cur_tile = out_channels_per_group - oc_start;
                if (cur_tile > OC_TILE) cur_tile = OC_TILE;
                float sum[OC_TILE];
                #pragma unroll
                for (int j = 0; j < OC_TILE; ++j) sum[j] = 0.0f;
                #pragma unroll
                for (int kh = 0; kh < kh_bound; ++kh) {
                    int ih_nom = oh + padding_h - kh * dilation_h;
                    if (ih_nom % stride_h != 0) continue;
                    int ih = ih_nom / stride_h;
                    if (ih < 0 || ih >= H) continue;
                    #pragma unroll
                    for (int kw = 0; kw < kw_bound; ++kw) {
                        int iw_nom = ow + padding_w - kw * dilation_w;
                        if (iw_nom % stride_w != 0) continue;
                        int iw = iw_nom / stride_w;
                        if (iw < 0 || iw >= W) continue;
                        for (int ic_local = 0; ic_local < in_channels_per_group; ++ic_local) {
                            int ic = g * in_channels_per_group + ic_local;
                            int input_idx = ((n * in_channels + ic) * H + ih) * W + iw;
                            float val = input[input_idx];
                            int base_weight_idx = ((ic_local * out_channels_per_group + oc_start) * kernel_h + kh) * kernel_w + kw;
                            #pragma unroll
                            for (int j = 0; j < OC_TILE; ++j) {
                                if (j < cur_tile) {
                                    int weight_idx = base_weight_idx + j * kernel_hw;
                                    sum[j] += val * s_weight[weight_idx];
                                }
                            }
                        }
                    }
                }
                #pragma unroll
                for (int j = 0; j < OC_TILE; ++j) {
                    if (j < cur_tile) {
                        int oc = g * out_channels_per_group + oc_start + j;
                        int output_idx = ((n * out_channels + oc) * H_out + oh) * W_out + ow;
                        output[output_idx] = sum[j];
                    }
                }
            }
        }
    }
}
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int groups)
{
    const int N = input.size(0);
    const int in_channels = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);
    const int out_channels_per_group = weight.size(1);
    const int kernel_h = weight.size(2);
    const int kernel_w = weight.size(3);
    const int out_channels = out_channels_per_group * groups;
    const int in_channels_per_group = in_channels / groups;
    const int H_out = (H - 1) * stride_h - 2 * padding_h + dilation_h * (kernel_h - 1) + 1;
    const int W_out = (W - 1) * stride_w - 2 * padding_w + dilation_w * (kernel_w - 1) + 1;
    auto output = torch::empty({N, out_channels, H_out, W_out}, input.options());
    const int weight_group_size = in_channels_per_group * out_channels_per_group * kernel_h * kernel_w;
    const size_t shared_mem_bytes = (size_t)weight_group_size * sizeof(float);
    const int spatial_elems = H_out * W_out;
    const int elements_per_tile = 1024;
    const int num_tiles = (spatial_elems + elements_per_tile - 1) / elements_per_tile;
    const dim3 blocks(groups, num_tiles);
    const int threads = 256;
    if (kernel_h == 3 && kernel_w == 5) {
        conv_transpose2d_kernel<3, 5><<<blocks, threads, shared_mem_bytes>>>(
            input.data_ptr<float>(),
            weight.data_ptr<float>(),
            output.data_ptr<float>(),
            N, in_channels, out_channels,
            H, W, H_out, W_out,
            kernel_h, kernel_w,
            stride_h, stride_w,
            padding_h, padding_w,
            dilation_h, dilation_w,
            groups,
            in_channels_per_group,
            out_channels_per_group,
            elements_per_tile
        );
    } else {
        conv_transpose2d_kernel<0, 0><<<blocks, threads, shared_mem_bytes>>>(
            input.data_ptr<float>(),
            weight.data_ptr<float>(),
            output.data_ptr<float>(),
            N, in_channels, out_channels,
            H, W, H_out, W_out,
            kernel_h, kernel_w,
            stride_h, stride_w,
            padding_h, padding_w,
            dilation_h, dilation_w,
            groups,
            in_channels_per_group,
            out_channels_per_group,
            elements_per_tile
        );
    }
    return output;
}
